import { resolveChannel } from '../helpers/resolve.js';
import { maybeInterval } from '../helpers/autoTicks.js';
import { bin as d3Bin, extent, thresholdFreedmanDiaconis, thresholdScott, thresholdSturges } from 'd3-array';
import { reduceOutputs } from '../helpers/reduce.js';
import { groupFacetsAndZ } from '../helpers/group.js';
import { isDate } from '../helpers/typeChecks.js';
import { ORIGINAL_NAME_KEYS } from '../constants.js';
const CHANNELS = {
    x: Symbol('x'),
    x1: Symbol('x1'),
    x2: Symbol('x2'),
    y: Symbol('y'),
    y1: Symbol('y1'),
    y2: Symbol('y2')
};
const ThresholdGenerators = {
    auto: thresholdScott,
    scott: thresholdScott,
    sturges: thresholdSturges,
    'freedman-diaconis': thresholdFreedmanDiaconis
};
function binBy(byDim, { data, ...channels }, options) {
    const { domain, thresholds = 'auto', interval } = options;
    const bin = d3Bin();
    if (domain)
        bin.domain(domain);
    if (interval) {
        const [lo, hi] = extent(data.map((d) => resolveChannel(byDim, d, channels)));
        const iv = maybeInterval(interval);
        if (iv)
            bin.thresholds(iv.range(lo, hi));
    }
    else if (thresholds)
        bin.thresholds(
        // use a generator
        typeof thresholds === 'string' && ThresholdGenerators[thresholds] !== undefined
            ? ThresholdGenerators[thresholds]
            : thresholds);
    // channels.x is the input
    bin.value((d) => resolveChannel(byDim, d, channels));
    // y, y1, y2, fill, stroke, etc are outputs
    const outputs = [
        ...(byDim === 'x' ? ['y', 'y1', 'y2'] : ['x', 'x1', 'x2']),
        'fill',
        'stroke',
        'r',
        'opacity',
        'fillOpacity',
        'strokeOpacity'
    ];
    let newChannels = {
        [byDim === 'x' ? 'insetLeft' : 'insetTop']: 0.5,
        [byDim === 'x' ? 'insetRight' : 'insetBottom']: 0.5,
        ...channels,
        [`${byDim}`]: CHANNELS[byDim], // `__${byDim}`,
        [`${byDim}1`]: CHANNELS[`${byDim}1`],
        [`${byDim}2`]: CHANNELS[`${byDim}2`],
        [ORIGINAL_NAME_KEYS[byDim]]: typeof channels[byDim] === 'string' ? channels[byDim] : null
    };
    const newData = [];
    let passedGroups = [];
    const bins = bin(data);
    ((options.cumulative ?? 0) < 0 ? bins.toReversed() : bins).forEach((group) => {
        const x0 = group.x0;
        const x1 = group.x1;
        const itemBinProps = {
            [CHANNELS[`${byDim}1`]]: x0,
            [CHANNELS[`${byDim}2`]]: x1,
            [CHANNELS[`${byDim}`]]: isDate(x0)
                ? new Date(Math.round((x0.getTime() + x1.getTime()) * 0.5))
                : ((x0 ?? 0) + (x1 ?? 0)) * 0.5
        };
        if (options.cumulative)
            passedGroups = [...passedGroups, ...group];
        const newGroupChannels = groupFacetsAndZ(options.cumulative ? passedGroups : group, channels, (items, itemGroupProps) => {
            const item = { ...itemBinProps, ...itemGroupProps };
            reduceOutputs(item, items, options, outputs, channels, newChannels);
            newData.push(item);
        });
        newChannels = { ...newChannels, ...newGroupChannels };
    });
    return { data: options.reverse ? newData.toReversed() : newData, ...newChannels };
}
/**
 * Bins on x. Also groups on y and the first channel of z, fill, or stroke, if any.
 *
 * @param param0
 * @param options
 */
export function binX({ data, ...channels }, options = { thresholds: 'auto', cumulative: false }) {
    return binBy('x', { data, ...channels }, options);
}
/**
 * Bins on y. Also groups on y and the first channel of z, fill, or stroke, if any.
 *
 * @param param0
 * @param options
 */
export function binY({ data, ...channels }, options = { thresholds: 'auto', cumulative: false }) {
    return binBy('y', { data, ...channels }, options);
}
/**
 * for binning in x and y dimension simultaneously
 */
export function bin({ data, ...channels }, options = { thresholds: 'auto', cumulative: false }) {
    const { domain, thresholds = 'auto', interval } = options;
    const binX = d3Bin();
    const binY = d3Bin();
    if (domain) {
        // this really doesn't make sense...
        binX.domain(domain);
        binY.domain(domain);
    }
    // channels.x is the input
    binX.value((d) => resolveChannel('x', d, channels));
    binY.value((d) => resolveChannel('y', d, channels));
    let yThresholds = [];
    if (interval) {
        const [xlo, xhi] = extent(data.map((d) => resolveChannel('x', d, channels)));
        const [ylo, yhi] = extent(data.map((d) => resolveChannel('y', d, channels)));
        const ivl = maybeInterval(interval);
        if (ivl) {
            binX.thresholds(ivl.range(xlo, xhi));
            binY.thresholds((yThresholds = ivl.range(ylo, yhi)));
        }
    }
    else if (thresholds) {
        // when binning in x and y, we need to ensure we are using consistent thresholds
        const t = typeof thresholds === 'string' && ThresholdGenerators[thresholds] !== undefined
            ? ThresholdGenerators[thresholds]
            : thresholds;
        binX.thresholds(t);
        binY.thresholds(t);
        yThresholds = binY(data)
            .slice(1)
            .map((g) => g.x0);
        binY.thresholds(yThresholds);
    }
    // y, y1, y2, fill, stroke, etc are outputs
    const outputs = ['fill', 'stroke', 'r', 'opacity', 'fillOpacity', 'strokeOpacity'];
    let newChannels = {
        inset: 0.5,
        ...channels,
        x: CHANNELS.x,
        x1: CHANNELS.x1,
        x2: CHANNELS.x2,
        y: CHANNELS.y,
        y1: CHANNELS.y1,
        y2: CHANNELS.y2,
        [ORIGINAL_NAME_KEYS.x]: typeof channels.x === 'string' ? channels.x : null,
        [ORIGINAL_NAME_KEYS.y]: typeof channels.y === 'string' ? channels.y : null
    };
    const groupBy = channels.z ? 'z' : channels.fill ? 'fill' : channels.stroke ? 'stroke' : true;
    const groupByPropName = groupBy !== true && typeof channels[groupBy] === 'string' ? channels[groupBy] : '__group';
    if (groupBy !== true)
        newChannels[groupBy] = groupByPropName;
    // consistent intervals
    const newData = [];
    binX(data).forEach((groupX) => {
        const gx0 = groupX.x0;
        const gx1 = groupX.x1;
        const newRecordBaseX = {
            [CHANNELS.x1]: gx0,
            [CHANNELS.x2]: gx1,
            [CHANNELS.x]: isDate(gx0)
                ? new Date(Math.round((gx0.getTime() + gx1.getTime()) * 0.5))
                : ((gx0 ?? 0) + (gx1 ?? 0)) * 0.5
        };
        const [ylo, yhi] = extent(groupX.map((d) => resolveChannel('y', d, channels)));
        const tExtentLo = yThresholds.filter((d) => d < ylo).at(-1) ?? ylo;
        const tExtentHi = yThresholds.filter((d) => d > yhi).at(0) ?? yhi;
        binY(groupX).forEach((groupY) => {
            if (groupY.length === 0)
                return;
            // The first bin.x0 is always equal to the minimum domain value,
            // and the last bin.x1 is always equal to the maximum domain value,
            // therefore we need to align with the thresholds
            const y1 = groupY.x0 === ylo ? tExtentLo : groupY.x0;
            const y2 = groupY.x1 === yhi ? tExtentHi : groupY.x1;
            const newRecordBaseY = {
                ...newRecordBaseX,
                [CHANNELS.y1]: y1,
                [CHANNELS.y2]: y2,
                [CHANNELS.y]: isDate(y1)
                    ? new Date(Math.round((y1.getTime() + y2.getTime()) * 0.5))
                    : ((y1 ?? 0) + (y2 ?? 0)) * 0.5
            };
            const newGroupChannels = groupFacetsAndZ(groupY, channels, (items, itemGroupProps) => {
                const newRecord = {
                    ...newRecordBaseY,
                    ...itemGroupProps
                };
                reduceOutputs(newRecord, items, options, outputs, channels, newChannels);
                newData.push(newRecord);
            });
            newChannels = { ...newChannels, ...newGroupChannels };
        });
    });
    return { data: options.reverse ? newData.toReversed() : newData, ...newChannels };
}
